#include <unordered_set>
using namespace std;

int main() {
    int x;
    cin >> x;

    unordered_set<int> visited;

    while (visited.insert(x).second) {
        ++x;
        while (x % 10 == 0)
            x /= 10;
    }

    cout << visited.size();
    return 0;
}

